const payload = $json.body ?? $json;
const expected = String($env.LEAD_EMPRESA_WEBHOOK_TOKEN || '').trim();
const received = String(payload.token || '').trim();
if (expected && received !== expected) {
  throw new Error('Token inválido para o webhook de leads do portal.');
}
const phone = String($env.PORTAL_LEAD_ALERT_PHONE || '').replace(/\D+/g, '');
if (!phone) {
  throw new Error('Configure PORTAL_LEAD_ALERT_PHONE no n8n com DDI e DDD.');
}
const lines = [
  '🏢 Novo lead de empresa no Portal Genesis IA',
  '',
  `Empresa: ${payload.empresa_nome || 'Não informada'}`,
  `Contato: ${payload.contato_nome || 'Não informado'}`,
  `WhatsApp: ${payload.whatsapp || 'Não informado'}`,
  `E-mail: ${payload.email || 'Não informado'}`,
  `Local: ${[payload.cidade, payload.estado].filter(Boolean).join(' - ') || 'Não informado'}`,
  `Quantidade estimada: ${payload.quantidade_vagas || 1}`,
  `Cargos: ${payload.cargos_interesse || 'Não informados'}`,
  payload.mensagem ? `Contexto: ${payload.mensagem}` : '',
].filter(Boolean);
return [{ json: {
  session: 'whats_junior',
  chatId: `${phone}@c.us`,
  text: lines.join('\n'),
  lead_id: payload.id || null
} }];
